{
  "loaded": [
    {
      "tool_id": "tool::c64::c64_run",
      "resource_identity": {
        "kind": "mcp",
        "serverName": "c64",
        "toolName": "c64_run"
      },
      "description": "Types the gated listing fresh, RUNs it on the real C64 for up to `frames` frames (default 3000, max 20000), and returns the contract heading, the C64's own error text (for example ?SYNTAX  ERROR IN 20), whether the title appeared, and the screens verbatim. The server presses the post-title keys itself; you cannot. The verdict comes only from this call, never from you.",
      "input_schema": {
        "type": "object",
        "properties": {
          "frames": {
            "default": 3000,
            "type": "integer",
            "minimum": 1,
            "maximum": 20000
          }
        },
        "additionalProperties": false
      }
    }
  ],
  "not_found": [],
  "tool_id_format": "resource-v2",
  "note": "Call tool_call with the same tool_id and arguments matching its input_schema. Load it again only if the schema is no longer in context."
}

{
  "loaded": [
    {
      "tool_id": "tool::c64::checksum_line",
      "resource_identity": {
        "kind": "mcp",
        "serverName": "c64",
        "toolName": "checksum_line"
      },
      "description": "Computes the magazine's checksum (:rem NNN) of a line number and body, and compares it with the printed checksum of that line in the current listing when it exists. Read-only: it changes nothing, touches no emulator and never edits a line.",
      "input_schema": {
        "type": "object",
        "properties": {
          "lineno": {
            "type": "integer",
            "minimum": 0,
            "maximum": 63999
          },
          "body": {
            "type": "string",
            "maxLength": 1000
          }
        },
        "required": [
          "lineno",
          "body"
        ],
        "additionalProperties": false
      }
    }
  ],
  "not_found": [],
  "tool_id_format": "resource-v2",
  "note": "Call tool_call with the same tool_id and arguments matching its input_schema. Load it again only if the schema is no longer in context."
}

{
  "loaded": [
    {
      "tool_id": "tool::c64::apply_patch",
      "resource_identity": {
        "kind": "mcp",
        "serverName": "c64",
        "toolName": "apply_patch"
      },
      "description": "Proposes a fix to the listing: 1 to 4 ops, each {op:'replace', lineno, new_body} or {op:'renumber', lineno, new_lineno}, and a reason. The checksum gate judges it and may refuse it; its refusal text names the printed and the computed checksum. It cannot insert or delete a line. An accepted patch is typed into the C64 but not run: call c64_run next. force_unverified works only after two refusals of that line.",
      "input_schema": {
        "type": "object",
        "properties": {
          "ops": {
            "minItems": 1,
            "maxItems": 4,
            "type": "array",
            "items": {
              "oneOf": [
                {
                  "type": "object",
                  "properties": {
                    "op": {
                      "type": "string",
                      "const": "replace"
                    },
                    "lineno": {
                      "type": "integer",
                      "minimum": 0,
                      "maximum": 63999
                    },
                    "new_body": {
                      "type": "string",
                      "maxLength": 1000
                    }
                  },
                  "required": [
                    "op",
                    "lineno",
                    "new_body"
                  ],
                  "additionalProperties": false
                },
                {
                  "type": "object",
                  "properties": {
                    "op": {
                      "type": "string",
                      "const": "renumber"
                    },
                    "lineno": {
                      "type": "integer",
                      "minimum": 0,
                      "maximum": 63999
                    },
                    "new_lineno": {
                      "type": "integer",
                      "minimum": 0,
                      "maximum": 63999
                    }
                  },
                  "required": [
                    "op",
                    "lineno",
                    "new_lineno"
                  ],
                  "additionalProperties": false
                }
              ]
            }
          },
          "reason": {
            "type": "string",
            "minLength": 1,
            "maxLength": 500
          },
          "force_unverified": {
            "default": false,
            "type": "boolean"
          }
        },
        "required": [
          "ops",
          "reason"
        ],
        "additionalProperties": false
      }
    }
  ],
  "not_found": [],
  "tool_id_format": "resource-v2",
  "note": "Call tool_call with the same tool_id and arguments matching its input_schema. Load it again only if the schema is no longer in context."
}

{
  "loaded": [
    {
      "tool_id": "tool::c64::c64_press",
      "resource_identity": {
        "kind": "mcp",
        "serverName": "c64",
        "toolName": "c64_press"
      },
      "description": "Presses keys on the C64 while a program waits for input, for example the key the title screen asks for. Only the keys the listing's title screen allows are accepted; any other key refuses the whole call and nothing is pressed. It cannot type program text and is never evidence for a verdict. Entries: one printable ASCII character, RETURN or SPACE (1 to 16).",
      "input_schema": {
        "type": "object",
        "properties": {
          "keys": {
            "minItems": 1,
            "maxItems": 16,
            "type": "array",
            "items": {
              "type": "string",
              "minLength": 1,
              "maxLength": 6
            }
          }
        },
        "required": [
          "keys"
        ],
        "additionalProperties": false
      }
    }
  ],
  "not_found": [],
  "tool_id_format": "resource-v2",
  "note": "Call tool_call with the same tool_id and arguments matching its input_schema. Load it again only if the schema is no longer in context."
}

