      "tool_id": "tool::c64::c64_reload",
      "resource_identity": {
        "kind": "mcp",
        "serverName": "c64",
        "toolName": "c64_reload"
      },
      "description": "Types the current gated (canonical) listing into the real C64 again, after NEW, and reports the listing hash and every line the C64 cannot store (untypeable). Takes no arguments: it cannot type text you supply, runs nothing and gives no verdict.",
